<template><view class="page"><view class="card"><text class="title">个人资料</text><text class="label">姓名</text><input v-model="form.name" class="input"/><text class="label">与老人关系</text><input v-model="form.relation" class="input"/><text class="label">手机号</text><input v-model="form.phone" class="input" type="number"/><text class="label">主要照护人</text><view class="row"><text>接收主要照护提醒</text><switch :checked="form.primary" color="#326a53" @change="e=>form.primary=e.detail.value"/></view><button class="save" @tap="save">保存资料</button></view></view></template><script>export default{data(){return{form:{name:'小敏',relation:'女儿',phone:'13800138000',primary:true}}},methods:{save(){uni.setStorageSync('family_profile',this.form);uni.showToast({title:'保存成功',icon:'success'});setTimeout(()=>uni.navigateBack(),400)}}}</script><style scoped>.page{min-height:100vh;padding:28rpx;background:#f6f7f3}.card{padding:30rpx;background:#fff;border-radius:28rpx}.title{display:block;font-size:34rpx;font-weight:900;color:#30443a}.label{display:block;margin:24rpx 0 10rpx;font-size:22rpx;color:#718078}.input{height:82rpx;padding:0 20rpx;border-radius:18rpx;background:#f4f6f3}.row{display:flex;justify-content:space-between;align-items:center;margin-top:26rpx}.save{margin-top:34rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>